Here is the root cause:
The `fend` calculation in `netfs_read_unlock_folios()` was using `umin(fpos + fsize, rreq->i_size)`, which truncated the folio's end to the file's EOF. This caused the folio to be unlocked when collected read results reached EOF, even though a ZERO subrequest handling the trailing bytes beyond EOF (within the same folio) had not yet completed. As a result, user-space could see uninitialized data via mmap.

Here is the patch:
  */
 static void netfs_read_unlock_folios(struct netfs_io_request *rreq,
 				     unsigned int *notes)
 {
 	struct folio_queue *folioq = rreq->buffer.tail;
 	unsigned long long collected_to = rreq->collected_to;
 	unsigned int slot = rreq->buffer.first_tail_slot;

 	if (rreq->cleaned_to >= rreq->collected_to)
 		return;

 	// TODO: Begin decryption

 	if (slot >= folioq_nr_slots(folioq)) {
 		folioq = rolling_buffer_delete_spent(&rreq->buffer);
 		if (!folioq) {
 			rreq->front_folio_order = 0;
 			return;
 		}
 		slot = 0;
 	}

 	for (;;) {
 		struct folio *folio;
 		unsigned long long fpos, fend;
 		unsigned int order;
 		size_t fsize;

 		if (*notes & COPY_TO_CACHE)
 			set_bit(NETFS_RREQ_FOLIO_COPY_TO_CACHE, &rreq->flags);

 		folio = folioq_folio(folioq, slot);
 		if (WARN_ONCE(!folio_test_locked(folio),
 			      "R=%08x: folio %lx is not locked\n",
 			      rreq->debug_id, folio->index))
 			trace_netfs_folio(folio, netfs_folio_trace_not_locked);

 		order = folioq_folio_order(folioq, slot);
 		rreq->front_folio_order = order;
 		fsize = PAGE_SIZE << order;
 		fpos = folio_pos(folio);
-		fend = umin(fpos + fsize, rreq->i_size);
+		fend = fpos + fsize;

 		trace_netfs_collect_folio(rreq, folio, fend, collected_to);

 		/* Unlock any folio we've transferred all of. */
 		if (collected_to < fend)
 			break;

 		netfs_unlock_read_folio(rreq, folioq, slot);
 		WRITE_ONCE(rreq->cleaned_to, fpos + fsize);
 		*notes |= MADE_PROGRESS;

 		clear_bit(NETFS_RREQ_FOLIO_COPY_TO_CACHE, &rreq->flags);

 		/* Clean up the head folioq.  If we clear an entire folioq, then
 		 * we can get rid of it provided it's not also the tail folioq
 		 * being filled by the issuer.
 		 */
 		folioq_clear(folioq, slot);
 		slot++;
 		if (slot >= folioq_nr_slots(folioq)) {
 			folioq = rolling_buffer_delete_spent(&rreq->buffer);
 			if (!folioq)
 				goto done;
 			slot = 0;
 			trace_netfs_folioq(folioq, netfs_trace_folioq_read_progress);
 		}

 		if (fpos + fsize >= collected_to)
 			break;
 	}

 	rreq->buffer.tail = folioq;
 done:
 	rreq->buffer.first_tail_slot = slot;
 }



